// Clean the lead from the FastAPI app. Only the body is kept: the request headers (with the token) stay behind.
const lead = $json.body;
const oneLine = (s) => (s ?? '').replace(/\s+/g, ' ').trim();
// Messages keep their line breaks, but runs of spaces and empty lines shrink to one.
const text = (s) => (s ?? '').replace(/[ \t]+/g, ' ').replace(/\n\s*\n+/g, '\n').trim();
const received = DateTime.fromISO(lead.receivedAt);

return [{
  json: {
    leadId: lead.leadId,
    source: lead.source,
    externalId: lead.externalId ?? null,
    receivedAt: lead.receivedAt,
    receivedAtKyiv: received.setZone('Europe/Kyiv').toFormat('yyyy-LL-dd HH:mm'),
    submittedAt: lead.submittedAt,
    name: oneLine(lead.name),
    email: oneLine(lead.email).toLowerCase(),
    phone: lead.phone ? oneLine(lead.phone) : null,
    message: text(lead.message),
    locale: lead.locale,
    pageUrl: lead.pageUrl ?? null,
  },
}];

// Stands in for Claude: no API call, no key, no cost. LLM_MODE=mock gives a fixed valid answer,
// LLM_MODE=mock-fail simulates an LLM that did not answer (to test the needsReview path).
const mode = $env.LLM_MODE || 'mock';
if (mode === 'mock-fail') {
  return [{ json: { rawText: '', model: 'mock', inputTokens: 0, outputTokens: 0, latencyMs: 0, llmError: 'Simulated LLM failure (LLM_MODE=mock-fail)' } }];
}

const language = $('Enrich').first().json.languageGuess;
const classification = {
  category: 'other',
  priority: 'medium',
  language,
  summary: 'Mock classification: no LLM was called.',
  replyDraft: language === 'uk'
    ? 'Дякуємо за ваше повідомлення! Ми відповімо найближчим часом. (тестова чернетка)'
    : 'Thank you for your message! We will get back to you soon. (mock draft)',
  confidence: 0.9,
};
return [{ json: { rawText: JSON.stringify(classification), model: 'mock', inputTokens: 0, outputTokens: 0, latencyMs: 0, llmError: null } }];

// One record with everything known about the lead: the input for Airtable and the webhook answer.
const lead = $('Normalise').first().json;
const enrich = $('Enrich').first().json;
const llm = $('LLM result').first().json;
const checked = $json;
const c = checked.classification;
const needsReview = checked.needsReview || Boolean(llm.llmError);
const issues = llm.llmError ? [llm.llmError, ...checked.issues] : checked.issues;

const record = {
  ...lead,
  category: c.category,
  priority: c.priority,
  language: c.language,
  summary: c.summary,
  replyDraft: c.replyDraft,
  confidence: c.confidence,
  needsReview,
  issues,
  rawText: checked.rawText,
  emailDomain: enrich.emailDomain,
  freeMail: enrich.freeMail,
  disposable: enrich.disposable,
  phoneCountry: enrich.phoneCountry,
  model: llm.model,
  inputTokens: llm.inputTokens,
  outputTokens: llm.outputTokens,
  costUsd: checked.costUsd,
  latencyMs: llm.latencyMs,
};

return [{
  json: {
    leadId: lead.leadId,
    record,
    // What the demo form shows. No personal data beyond what the visitor just typed.
    triage: { classification: c, needsReview, issues, model: llm.model, costUsd: checked.costUsd, enrich },
  },
}];
